from pathlib import Path
from html import escape
import json
from overview import render_overview
from leaderboard import render_leaderboard

root=Path(__file__).resolve().parents[1]
chapters=json.loads((root/'assets/hero-chapters.json').read_text(encoding='utf-8'))
demos=json.loads((root/'assets/demos/manifest.json').read_text(encoding='utf-8'))
facts=json.loads((Path(__file__).with_name('benchmark-results.json')).read_text(encoding='utf-8'))
models=[r for r in facts['results']['rows'] if r[1]!='Adapted']
assert len(demos)>=20
cards=[]
for i,d in enumerate(demos):
    feature=i<2 or i>=len(demos)-2
    cards.append(f'''<article class="demo-card{' feature' if feature else ''}" data-environment="{escape(d['environment'])}"><div class="demo-media"><video muted loop playsinline controls preload="none" data-src="{escape(d['src'])}" poster="{escape(d['poster'])}" aria-label="Example {i+1}: {escape(d['title'])}"></video></div><div class="demo-caption"><span class="demo-index">{i+1:02d}</span><div><h3>{escape(d['title'])}</h3><p>{escape(d['instruction'])}</p></div><span class="demo-environment">{escape(d['environment'])}</span></div></article>''')
filters=['<button class="demo-filter active" data-environment="all" aria-pressed="true">All <span>'+str(len(demos))+'</span></button>']
for env in ['Home','Kitchen','Office','Hospital','Industry','Laboratory','Public']:
    n=sum(d['environment']==env for d in demos)
    if n: filters.append(f'<button class="demo-filter" data-environment="{env}" aria-pressed="false">{env} <span>{n}</span></button>')
envs=[('Industrial workspace',20.8,'#247f73'),('Office',16.9,'#83a48b'),('Home',12.6,'#57aa9b'),('Kitchen',9.9,'#a5c2ab'),('Shopping mall',9.9,'#6d9980'),('Hospital',9.6,'#adcfc4'),('Warehouse',8.8,'#78948d'),('Laboratory',7.7,'#bdc9bb'),('Public space',1.5,'#91ad7b'),('Outdoor',1.2,'#8fa477'),('Other',1.1,'#d5e0da')]
envbar=''.join(f'<span style="width:{v}%;background:{color}" title="{label}: {v}%"></span>' for label,v,color in envs)
envkey=''.join(f'<span><i style="background:{color}"></i>{label}<b>{v}%</b></span>' for label,v,color in envs)
timeline=''.join(f'<button class="case-step" data-clip="{i}" aria-label="Play example {i+1:02d}" aria-pressed="{"true" if i==0 else "false"}"><span class="case-number">{i+1:02d}</span><span class="case-progress"><i></i></span></button>' for i in range(len(chapters)))

html='''<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#147d73"><title>EmbodiSafety: Risk Understanding and Response in Embodied AI</title>
<meta name="description" content="Explore EmbodiSafety through DEMO_TOTAL visual demonstrations, a dataset of 1,632 safety decisions, and model evaluations across Snapshot and Trajectory tracks."><meta property="og:type" content="website"><meta property="og:title" content="EmbodiSafety: Benchmarking Risk Understanding and Response in Embodied AI"><meta property="og:description" content="A visual benchmark for embodied safety: 1,632 tasks, 844 scenarios, and six response modes."><meta property="og:url" content="https://embodisafety-1.github.io/"><meta property="og:image" content="https://embodisafety-1.github.io/assets/figures/web-overview.webp"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://embodisafety-1.github.io/"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="styles.css"><script src="app.js" defer></script><script src="i18n.js" defer></script></head>
<body><a class="skip-link" href="#overview">Skip to overview</a><nav class="topnav" id="topnav" aria-label="Main navigation"><div class="nav-inner"><a href="#top" class="brand">EmbodiSafety<span class="brand-mark" aria-hidden="true">/</span></a><div class="nav-links" id="navLinks"><a href="#overview">Overview</a><a href="#demos">Demos</a><a href="#dataset">Dataset</a><a href="#results">Results</a></div><div class="nav-actions"><button class="language-toggle" id="languageToggle" type="button" aria-label="Switch language">中文 / English</button><a class="nav-paper" href="#" data-coming="Paper">Paper ↗</a><a class="nav-github" href="#" data-coming="GitHub">GitHub ↗</a></div><button id="navToggle" class="nav-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="navLinks"><span></span><span></span></button></div></nav>
<main><header class="hero" id="top"><video id="heroVideo" class="hero-video" muted loop playsinline preload="auto" poster="assets/posters/refuse-pharmacy-theft.webp" aria-label="Three selected EmbodiSafety examples played continuously"><source src="assets/videos/hero-examples.mp4" type="video/mp4"></video><div class="hero-shade"></div><div class="hero-head"><p class="hero-kicker">Embodied AI safety benchmark</p><h1><span class="h1-name">EmbodiSafety</span><span class="h1-title">Benchmarking Risk Understanding<br>and Response in Embodied AI</span></h1><p class="subtitle">A visual benchmark for understanding risk and choosing safe responses.</p></div><div class="hero-footer"><div class="hero-example-nav"><span class="sequence-count" id="currentScene">01 / 03</span><div class="case-timeline" role="group" aria-label="Example sequence">CASE_TIMELINE</div><button id="heroPlay" type="button" aria-label="Pause background video" aria-pressed="false">Ⅱ</button></div></div></header>

<section class="overview section" id="overview" aria-labelledby="overview-title"><div class="content-wrap"><div class="section-heading"><p class="section-kicker">01 / Overview</p><h2 id="overview-title">EmbodiSafety in one view.</h2></div>NATIVE_OVERVIEW<div class="overview-text"><p>EmbodiSafety evaluates how embodied agents interpret environmental risks and turn that understanding into a safe next step. The benchmark contains <strong>1,632 tasks across 844 visual scenarios</strong>, from routine household manipulation to medical and industrial settings. Snapshot tasks test decisions from a single image. Trajectory tasks add an ordered visual history, including situations that call for autonomous recovery or human intervention.</p><p>Each response is assessed for its <strong>response mode, risk explanation, and actionable handling</strong>. A complete decision must pass every applicable check. This connects hazard recognition to the action an agent would take, and makes the boundary between continuing, adapting, and seeking help part of the evaluation.</p></div></div></section>

<section class="demos section" id="demos" aria-labelledby="demos-title"><div class="wide-wrap"><div class="gallery-heading"><div class="section-heading"><p class="section-kicker">02 / Visual demonstrations</p><h2 id="demos-title">Everyday tasks, changing risks.</h2></div><button class="gallery-motion" id="galleryMotion" aria-pressed="false">Pause videos</button></div><div class="demo-toolbar"><div class="demo-filters" role="group" aria-label="Filter demonstrations by environment">DEMO_FILTERS</div><span id="demoCount" aria-live="polite">DEMO_TOTAL examples</span></div><div class="demo-gallery" id="demoGallery">DEMO_CARDS</div></div></section>

<section class="dataset section" id="dataset" aria-labelledby="dataset-title"><div class="content-wrap"><div class="section-heading"><p class="section-kicker">03 / The dataset</p><h2 id="dataset-title">One scene or a visual history.</h2><p class="section-description">Both tracks pair a user instruction with visual evidence and a reference decision. They differ in how much of the unfolding situation the model can observe.</p></div><div class="dataset-facts"><dl><dt>Decision tasks</dt><dd>1,632</dd></dl><dl><dt>Trajectory data</dt><dd>540</dd></dl><dl><dt>Snapshot data</dt><dd>1,092</dd></dl><dl><dt>Response modes</dt><dd>6</dd></dl></div><div class="track-pair"><article class="track" data-track="snapshot"><header><h3>Snapshot</h3><span>1,092 tasks · 1 image</span></header><p>The model judges the current scene: whether a task is safe, harmful, underspecified, or admissible under explicit constraints. Four response modes cover proceeding, refusing, asking for clarification, and constrained execution.</p></article><article class="track" data-track="trajectory"><header><h3>Trajectory</h3><span>540 tasks · 2–8 frames</span></header><p>Ordered observations reveal how risks develop during execution. This track includes all six response modes, adding autonomous recovery and human escalation when a task encounters failure.</p></article></div><div class="environment-mixture"><h3>Scenario environments</h3><div class="environment-bar" role="img" aria-label="Environment distribution: industrial workspace 20.8%, office 16.9%, home 12.6%, kitchen 9.9%, shopping mall 9.9%, hospital 9.6%, warehouse 8.8%, laboratory 7.7%, public space 1.5%, outdoor 1.2%, other 1.1%.">ENV_BAR</div><div class="environment-key">ENV_KEY</div></div></div></section>

<section class="results section" id="results" aria-labelledby="results-title"><div class="content-wrap"><div class="section-heading"><p class="section-kicker">04 / Benchmark results</p><h2 id="results-title">Complete-decision accuracy.</h2><p class="section-description">The strongest evaluated model, Claude-Opus-5.5, reaches 56.1% on Snapshot and 61.5% on Trajectory.</p></div>NATIVE_LEADERBOARD</div></section>

</main>
<footer class="site-footer"><div class="content-wrap"><div class="footer-links"><a href="#" data-coming="Paper">Paper ↗</a><a href="#" data-coming="GitHub">GitHub ↗</a><a href="#top">Top ↑</a></div></div></footer><script id="heroChapters" type="application/json">HERO_CHAPTERS</script></body></html>'''
for token,value in [('NATIVE_LEADERBOARD',render_leaderboard(models)),('NATIVE_OVERVIEW',render_overview(models)),('DEMO_TOTAL',str(len(demos))),('CASE_TIMELINE',timeline),('DEMO_FILTERS',''.join(filters)),('DEMO_CARDS','\n'.join(cards)),('ENV_BAR',envbar),('ENV_KEY',envkey),('HERO_CHAPTERS',json.dumps(chapters).replace('<','\\u003c'))]:
    html=html.replace(token,value)
(root/'index.html').write_text(html,encoding='utf-8')
print('Page built:',len(demos),'demos;',len(chapters),'hero scenes;',len(models),'evaluated models.')
